      "moduleId": "exam-two-module-12",
      "label": "Core contraction and envelope expansion",
      "teaching": "When usable core hydrogen is exhausted, an inert helium core contracts and heats. Hydrogen surrounding that core can fuse in a shell. Core contraction continues while shell burning becomes more intense, and the outer envelope expands and cools. The star can be both more luminous and cooler at its surface because its radiating area becomes much larger. The detailed core–shell–envelope coupling is complex; the source explicitly cautions against a single oversimplified mechanical story. On the H–R diagram, the track moves toward cooler temperatures as the envelope expands, then climbs the giant branch.",
