  "qualifications": [
    {
      "title": "Optional formula",
      "source": "L14 p16",
      "text": "The absolute-magnitude-to-luminosity conversion is explicitly “No need to know this.” It remains a source reference, excluded from scored tasks."
    },
    {
      "title": "Displayed luminosity key",
      "source": "L14 p17 / Top Hat Q4",
      "text": "A supplied luminosity question leaves necessary assumptions unspecified and is excluded from scoring."
    },
    {
      "title": "Apparent versus intrinsic brightness",
      "source": "L15 p14",
      "text": "Equal temperature plus “brighter” does not distinguish larger radius from smaller distance. Original radius questions specify luminosity or equal distances."
    },
    {
      "title": "H–R radius powers",
      "source": "L16 p22 / L15 p8",
      "text": "The radius trend is qualitative on p22. Exact comparisons use R ∝ √L/T² from the supplied luminosity equation."
    },
    {
      "title": "Dust absorption",
      "source": "L17 p17",
      "text": "The slide emphasizes scattering. Dust also absorbs light; the absolute “not absorbed” wording is not used as a graded fact.",
      "url": "https://cesar.esa.int/upload/201807/exploring_the_ism_teacher_guide.pdf"
    },
    {
      "title": "Herbig–Haro details",
      "source": "L17 p21",
      "text": "Star-birth association and axis alignment are taught. The slide’s universal lifetime/composition wording is excluded from scoring; NASA describes young-star jets and shocks.",
      "url": "https://science.nasa.gov/missions/hubble/hubble-movies-provide-unprecedented-view-of-supersonic-jets-from-young-stars/"
    },
    {
      "title": "Lecture credit",
      "source": "L18 p1",
      "text": "Lecture 18 credits Dr. Rob Hynes; earlier supplied covers credited Prof. Manos Chatzopoulos. Preserve those source attributions. The actual Exam 1 evidence calibrates observed task style without assuming the lecturer identity is unchanged."
    },
    {
      "title": "Internal versus surface heating",
      "source": "L18 pp17–20",
      "text": "Contraction releases gravitational energy and heats the interior. Surface-temperature tracks depend on phase and mass; do not require a monotonic increase in surface temperature or total luminosity.",
      "url": "https://openstax.org/books/astronomy/pages/21-2-the-h-r-diagram-and-the-study-of-stellar-evolution"
    },
    {
      "title": "Pressure balance and continuing energy loss",
      "source": "L18 pp12, 18–19",
      "text": "The pressure–gravity story separates mechanical support from ongoing energy replacement. Approximate balance can coexist with slow contraction; the broad final-gravity slogan is not used as a universal collapse claim.",
      "url": "https://openstax.org/books/astronomy/pages/21-1-star-formation"
    },
    {
      "title": "Selected answer is not a graded key",
      "source": "Lecture 18 supplied capture",
      "text": "The new capture shows a selected response without a visible grading result. Source review distinguishes selected, displayed-credited and independently source-supported answers."
    },
    {
      "title": "Two stellar clocks",
      "source": "L19 pp6–8,16–19",
      "text": "Kelvin–Helmholtz time scales as M²/(RL); main-sequence lifetime approximately as M/L. Compare under the explicitly held conditions. Neither is an exact all-phase age formula."
    },
    {
      "title": "Temperature powers and iron",
      "source": "L20 pp10,13",
      "text": "T⁴, T¹⁶, and T⁴¹ are local course approximations. Iron-group fusion does not provide the continuing energy source; heavier elements can still form through other processes."
    },
    {
      "title": "Composition and pressure",
      "source": "L20 pp7–9",
      "text": "Helium enrichment reduces free-particle number at the same mass density and temperature. At equal particle density and temperature, ideal-gas pressure is unchanged."
    },
    {
      "title": "Internal flash and stellar mass",
      "source": "L20 pp23–25",
      "text": "The helium flash is an internal low-mass-star event, not a visible supernova. The supplied post-ignition direction is down/left. Do not universalize this ignition mode to all masses."
    },
    {
      "title": "Dated and reference claims",
      "source": "L20 p8; L21 pp24,27,31",
      "text": "Faint-young-Sun climate estimates, Population III observation status, tentative Eta Carinae companion wording, and the coefficient-rich Cepheid calibration remain qualified reference material. They are not new memorization targets."
    },
    {
      "title": "Visible wrong response",
      "source": "L20 supplied capture; p16",
      "text": "B in the hydrogen-burning pair was awarded 0/1. The capture provides no correct key; pp+CNO is independently supported by the lecture. Retain selected response, grade, and supported answer separately."
    }
  ],
